import{z as i,x as l,o as E,c as B,q as t,j as r,D as e,d as A,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"S3 对象存储语义","description":"","frontmatter":{"title":"S3 对象存储语义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/object-storage-s3.md","filePath":"cs/object-storage-s3.md","lastUpdated":1791413859000}'),p={name:"cs/object-storage-s3.md"};function d(c,a,m,T,_,h){const s=l("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="s3-对象存储语义" tabindex="-1">S3 对象存储语义 <a class="header-anchor" href="#s3-对象存储语义" aria-label="Permalink to &quot;S3 对象存储语义&quot;">​</a></h1><div class="epigraph"><p>对象是不可改字节的 PUT/GET，键空间扁平。成功 PUT 的可见性曾是最终一致，后来读己之写加强，仍不是任意并发的线性一致文件。</p><footer>—— 据 Amazon S3 公开一致性声明的演进；对象存储与 POSIX 对照整理</footer></div><p>上一课<a href="/cs/gfs-hdfs">GFS</a>是层次文件与可追加块。缺口是<strong>另一种 API</strong>：整对象替换、HTTP、无限键。本课钉对象语义与一致性档，不把 AWS 商业条款当定理。后课分布式文件元数据对比「目录与 inode」为什么更难。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对象：不可部分改（除了分段上传合成）。覆盖 PUT 是新世代。列表、覆盖、删除的交错曾出现「旧对象仍 GET 到」。2015 年后许多区域对新 PUT 提供 read-after-write；2020 年 Amazon 宣布强一致列表与覆盖——工程演进，应用仍须读当前文档，本课记：<strong>对象存储的 C 是产品档，不是 POSIX mtime 定理</strong>。</p><p>分段上传：完成前部分不可见；完成是原子换对象。并发两个 PUT 同一键：谁赢取决于服务的并发控制，不要假设与墙钟一致。</p><p><span class="marginnote">常见误区：初学者容易把对象存储当网盘或 NFS 目录用。实际上键空间是扁平的，「目录」只是键名里的前缀字符串，改一个「目录名」等于把里面每个键逐个复制删除，没有真正的 rename。</span></p><p><span class="marginnote">不要发明内部论文编号。公开设计谈话与产品文档是对象课的文献；内部 Dynamo 论文讲的是键值，不是 S3 API 全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 etag/版本号做条件写，接 fencing 思路。列表分页会在并发更新下漏或重，若要精确目录用自己的索引（元数据课）。不要把 S3 当 NFS。</p><p><span class="marginnote">术语翻译：etag 就是对象内容的指纹（常见实现是哈希）。条件写的意思是「指纹还等于我上次看到的 A 才允许替换」——若别人抢先改过，指纹对不上，写被拒绝，这就是在读己之写之上做的乐观锁。</span></p><p><span class="marginnote">数字实例：大对象靠分段并行吞吐。按每段最小 5 MB、最多一万段计，单个 10 GB 对象可拆成约 2000 段同时上传，耗时约等于最慢的一段，而不是一条连接传完 10 GB。</span></p>',12)),(E(),r(n,null,{default:e(()=>[o(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22PUT%20%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20VIS%5B%22%E5%8F%AF%E8%A7%81%E6%80%A7%E6%A1%A3%3A%20%E4%BA%A7%E5%93%81%E5%A3%B0%E6%98%8E%22%5D%0A%20%20MPU%5B%22%E5%88%86%E6%AE%B5%E4%B8%8A%E4%BC%A0%E5%AE%8C%E6%88%90%22%5D%20--%3E%20ATOM%5B%22%E6%8D%A2%E9%94%AE%E5%8E%9F%E5%AD%90%22%5D%0A%20%20GET%5B%22GET%22%5D%20--%3E%20ET%5B%22etag%20%2F%20%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与<a href="/cs/eventual-consistency">最终一致</a>：旧 S3 列表是最终；新声明更强，跨区域复制仍常异步——地理复制后课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>吞吐：大对象并行分段。小对象海量：元数据与 QPS 成为账单与限流，不是块大小 64MB 能救。与 GFS 主：对象存储把命名空间做成可水平扩展的索引，避免单 NameNode，代价是目录 listing 的规格更弱或更贵。</p><p>本课不写 Glacier 归档。也不写 Transformer 权重文件——那是另一栏，这里只是 blob。</p><p>失败：PUT 超时后可能已成功，重试无幂等键会双对象（不同键）或同一键覆盖。分段上传要 abort 孤儿。接<a href="/cs/idempotency-keys">幂等键</a>与<a href="/cs/rpc-semantics">RPC</a>。</p>',5)),(E(),r(n,null,{default:e(()=>[o(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20PUT%20%E8%B6%85%E6%97%B6%22%5D%20--%3E%20Q%7B%22%E6%9C%8D%E5%8A%A1%E7%AB%AF%E5%85%B6%E5%AE%9E%E6%88%90%E5%8A%9F%E4%BA%86%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E6%88%90%E5%8A%9F%20%E5%90%8C%E9%94%AE%E6%97%A0%E6%9D%A1%E4%BB%B6%E9%87%8D%E8%AF%95%22%7C%20R1%5B%22%E8%A6%86%E7%9B%96%E4%B8%BA%E7%9B%B8%E5%90%8C%E5%86%85%E5%AE%B9%20%E6%97%A0%E5%AE%B3%22%5D%0A%20%20Q%20--%3E%7C%22%E6%88%90%E5%8A%9F%20%E5%B8%A6%E6%97%A7%20etag%20%E6%9D%A1%E4%BB%B6%E9%87%8D%E8%AF%95%22%7C%20R2%5B%22%E6%8C%87%E7%BA%B9%E4%B8%8D%E7%AC%A6%20%E8%A2%AB%E6%8B%92%20%E4%B8%8D%E9%87%8D%E5%A4%8D%E5%86%99%22%5D%0A%20%20Q%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%20%E6%8D%A2%E6%96%B0%E9%94%AE%E9%87%8D%E8%AF%95%22%7C%20R3%5B%22%E6%97%A0%E5%B9%82%E7%AD%89%E9%94%AE%20%E5%87%BA%E7%8E%B0%E5%8F%8C%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某云某日的一致性句子永远真，要读当时文档。后课默认：整对象原子替换；跨对象事务没有；listing 与跨区是弱档除非声明。下一课回到有目录树时元数据如何分片。</p><p>API 比文件系统简单，简单换来扩展；复杂语义要自己做。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对象 PUT 替换；分段完成才原子可见。</li><li>一致性档随产品演进，跨区复制仍常异步。</li><li>条件写用 etag；超时重试要当可能已成功。</li><li>出处：S3 公开一致性声明；对照 GFS POSIX 差距。</li></ul>',5))])}const D=i(p,[["render",d]]);export{P as __pageData,D as default};
